import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"ホストサービス","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/dev-guide/sdk/services.md","filePath":"ja-JP/dev-guide/sdk/services.md","lastUpdated":1787481584000}'),r={name:"ja-JP/dev-guide/sdk/services.md"};function a(i,e,s,n,l,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="ホストサービス" tabindex="-1">ホストサービス <a class="header-anchor" href="#ホストサービス" aria-label="Permalink to &quot;ホストサービス&quot;">​</a></h1><p><code>PluginSdk.Services</code> にある静的サービスで、ホストアプリの機能をプラグインに公開します——それぞれがホスト起動時に配線されるデリゲートを薄くラップした静的クラスなので、実際に裏で何が動いていてもプラグイン側の呼び出し方は変わりません。</p><table tabindex="0"><thead><tr><th>サービス</th><th>用途</th></tr></thead><tbody><tr><td><code>FuzzyMatchService</code></td><td><code>IsMatch(pattern, text)</code> — <code>text</code>(またはそのエイリアスのいずれか)が fzf 構文の <code>pattern</code> に一致するかどうかを、ホスト自身の検索が使っているのとまったく同じマッチングロジックで判定します。<code>GetHighlightMask(text, query)</code> — その組み合わせに対する文字単位のハイライトマスクを、ホスト自身の結果と同じリテラル/あいまい/エイリアスの多段フォールバック(中国語ピンインを含む)で計算します。これにより、プラグインの結果のハイライトも単純なリテラル部分一致だけでなく一貫した見た目になります。</td></tr><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> — 現在の言語に対してランタイムで文字列を取得します。<code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> — プラグイン自身が埋め込んだ JSON 翻訳を読み込みます。<code>GetSupportedCultures(assembly)</code>。<code>GetCurrentCulture()</code> — アプリで現在選択されている UI 言語(例:<code>&quot;zh-CN&quot;</code>)で、OS のシステムロケールとは独立したユーザー設定です。生のカルチャコードそのものが必要な場合(HTTP の <code>Accept-Language</code> ヘッダーに入れる、翻訳 API のターゲット言語を選ぶ、など)にのみこれを使ってください——<code>CultureInfo.CurrentUICulture</code> は OS のロケールを反映するもので、この設定とは別物であり、ユーザーの Windows の言語とアプリ内言語が異なる場合には静かに食い違います。</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> と <code>GetThumbnail(path, size)</code> — キャッシュ付きのシェルアイコン/サムネイル抽出で、プラグインが自分で Windows のアイコン API を呼び出す必要がありません。</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> — ユーザーの<a href="./../../user-guide/settings/favorites.html">お気に入り</a>一覧への読み取り専用アクセス(<code>FavoriteItem</code>:Name、Path)。</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryEntries()</code> — 記録済みの<a href="./../../user-guide/settings/history.html">履歴</a>エントリを、最近開いた順に <code>HistoryEntry { Keyword, Path, Kind, Time }</code> として返します(<code>Kind</code> は <code>HistoryEntryKind</code>:<code>File</code> / <code>Folder</code> / <code>Application</code>。<code>Keyword</code> はそこに至った検索テキストで、クエリを何も入力せず — 例えばクイックパネルのタブから — 直接開いた場合は空文字列です。<code>Time</code> は Unix 秒です)。各パスは最大1回だけ現れ、そのパスに最後にたどり着いたキーワードの下に紐付けられます。</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> — 現在の結果に<strong>まだ含まれていない</strong>パスに対する、バッチでの Size/Created/Modified/Accessed 取得(<a href="./abstractions.html#filemetadata"><code>FileMetadata</code></a>)です。すべての <code>ISearchResult</code> はすでに自身の <code>Metadata</code> プロパティを通じてこれを無料で保持しているため(<a href="./abstractions.html#isearchresult">共有抽象化</a>を参照)、このサービスを使う価値があるのは、何か別の方法で得たパス(例えば自分の設定由来のもの)に対してだけです。</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> — その仕組みを自前で再実装することなく、プラグインが自身のディレクトリをバックグラウンドインデックス作成や USN 監視の対象として登録できるようにします。<code>WatchDirectories(pluginId, onChanged)</code> は、<strong>あなたが登録した</strong>ディレクトリがディスク上で変化したときにコールバックし、購読をやめるための <code>IDisposable</code> を返します。ブロードキャストではなく登録者ごとなので、比べるべき id はなく、他人の変化に反応してしまうこともありません — その変化が誰の登録に属するかは、ホストがすでに知っていることです。バックグラウンドスレッドで、しかもデバウンス済みで呼ばれます(大量コピーはディレクトリが落ち着いたあとの1回であって、ファイルごとに1回ではありません)。通知されるのはホストがあなたのディレクトリに確かに帰属させられた変化だけで、帰属させられない場合(ツリー全体を置き換える再スキャンなど)は黙っているより呼ぶほうを選びます。<code>EnumerateDirectoryAsync(path, recursive, filterPattern, limit, token)</code> は、ファイルシステムではなくその同じインデックスからディレクトリの中身を列挙します — ホストがインデックスしているドライブならディスク I/O はまったく発生せず、そうでないディレクトリは自動的に実走査に切り替わるので、呼び出し側がどちらかを判断する必要はありません。ストリーミングで返り、<code>filterPattern</code> が絞るのは<strong>ファイル</strong>です(ディレクトリは常に返るので、不要なら <code>IsDir</code> で落としてください)。隠しファイルとシステム項目は決して返りません。再帰列挙では <code>limit</code> を設定する価値があります — <code>EnumerateDirectoryAsync(@&quot;C:\\&quot;, recursive: true)</code> は、ボリューム上の全項目を要求どおりきっちり返します。</td></tr><tr><td><code>RecentFilesService</code></td><td><code>GetRecentFilesAsync(directories, limit, maxAgeMinutes, token)</code> — 一連のディレクトリ配下で最も新しい項目を、新しい順に返します。ディスクではなくホストのメモリ上のインデックスが答えます。ディレクトリごとではなく、全体を<strong>1つ</strong>にマージした一覧です。ファイルのみ:フォルダー自身の更新日時は、中に何かが追加・削除されるたびに変わるため、「何を作業したか」を見せるはずの一覧の先頭に「作業中のフォルダー」が並んでしまいます。<code>limit</code> に 0 で件数無制限、<code>maxAgeMinutes</code> に 0 で期間無制限ですが、どちらも設定しないと、単に新しいものがないという理由だけで、放置されたフォルダーが1か月前のファイルを出し続けます。ホストがインデックスしていないディレクトリはその場で走査されず、単に何も寄与しません — ここで欲しいのは速い答えか、さもなくば無しです。遅いほうは <code>DirectoryIndexerService.EnumerateDirectoryAsync</code> があります。</td></tr><tr><td><code>ExplorerPathService</code></td><td><code>GetLastActivePath()</code> — エクスプローラーのウィンドウやファイルダイアログが最後に表示していたフォルダー。一度もなければ <code>null</code>。ホスト自身のウィンドウ追跡が埋めており、Lertaro 自身の UI だけでなく<strong>あらゆる</strong>アプリケーションのファイルダイアログを見ているため、「ユーザーが最後に実際に見ていたフォルダー」を意味します — プラグインが自力で割り出せるものではありません。<a href="./core-search-actions.html"><code>IActivePathCollector</code></a> とは逆方向です:あちらはサードパーティのファイルマネージャーが何を表示しているかをプラグインがホストに<strong>伝える</strong>もの、こちらは尋ねるものです。まだ存在する保証はありません:記録しているのはユーザーが行った先であり、そのフォルダーはすでに削除されたり取り外されたりしているかもしれません。</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> — ホストの設定ストアから、プラグイン自身の永続化済み設定への読み取り専用アクセスです。3段階でフォールバックします。ユーザーが一度でも保存していればその永続化された値、何も保存されていなければあなたの <code>IConfigurable</code> スキーマにおけるそのフィールド自身の <code>DefaultValue</code>、それもなければ最後の手段としてあなたが渡した <code>defaultValue</code> 引数、という順です。したがって、スキーマで宣言されたデフォルト値が唯一の信頼できる情報源となり、呼び出し側のコードに同じデフォルト値をもう一度ハードコードする必要がありません。設定を毎回読み直すのではなくキャッシュする場合は、<code>SettingChanged(pluginId, key)</code> イベントを購読し、自分のプラグインに対して発火したタイミングでキャッシュを破棄してください——ホストは設定ページでの保存の直後にこれを発火させます。これがキャッシュを無効化できる唯一の信頼できるタイミングです(キー入力ごとのチェックやポーリングでは、たまたま何かがトリガーされるまで変化に気づけないか、あるいは永久に気づけません)。</td></tr><tr><td><code>SearchRefreshService</code></td><td><code>RefreshIfMatches(queryMatches)</code> — データが非同期に届く <code>IInstantResultProvider</code>(<a href="./core-search-actions.html#iinstantresultprovider"><code>IInstantResultProvider</code></a>を参照)向けです。バックグラウンドの取得処理が完了し結果をキャッシュしたら、現在のクエリ文字列に対する述語を指定してこれを呼び出してください。ホストはその述語に一致するアクティブな検索をすべて再実行するため、ユーザーが何も入力し直さなくても、キャッシュ済みの結果がそのまま表示されるようになります。</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> — App のログファイルに書き込み、ホスト自身のログ行とまったく同じように <strong>設定 → サービスの状態 → App</strong> に表示されます。</td></tr><tr><td><code>PluginPromptService</code></td><td><code>Prompt(title, fields, initialValues?)</code> — 指定された <a href="./abstractions.html#iconfigurable"><code>PluginConfigField</code></a> の値をユーザーに尋ねる小さなモーダルを表示します(<code>IConfigurable</code> の設定ダイアログが使っているのと同じフィールドスキーマ/描画ロジックです)。<code>Key</code> で一致する <code>initialValues</code> があればそれで、なければ各フィールド自身の <code>DefaultValue</code> で事前入力されます。入力された値をフィールドの <code>Key</code> をキーとして返し、ユーザーがキャンセルした場合は <code>null</code> を返します——これらの値はプラグインの実際の永続化済み設定から読み取られたり、そこに書き込まれたりすることは一切ないため、実際の設定項目に触れることなく、設定フィールドのスキーマを一度限りの入力(例:「追加する前に名前を付ける」)のためだけに安心して再利用できます。</td></tr><tr><td><code>UserDataService</code></td><td><code>GetUserDataDirectory()</code> — 現在のユーザー専用のデータディレクトリ（インストール版の <code>%LOCALAPPDATA%\\Lertaro</code> やポータブル版の <code>Data\\Users\\&lt;hash&gt;</code> など）を返し、ユーザー固有の設定やプラグインデータを保存します。<code>GetSharedDataDirectory()</code> — マシン全体の共有データディレクトリ（インストール版の <code>%PROGRAMDATA%\\Lertaro</code> やポータブル版の <code>Data\\Machine</code> など）を返し、複数ユーザー間で共有されるランタイム（Python / Node.js 埋め込み環境など）やグローバルキャッシュを保存します。</td></tr></tbody></table><p><code>LogLevel</code> は <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code> で、<a href="./../../user-guide/settings/service-status.html">サービスの状態のログビューアー</a>のレベルフィルターと一致します。</p><h2 id="シェルのファイル操作" tabindex="-1">シェルのファイル操作 <a class="header-anchor" href="#シェルのファイル操作" aria-label="Permalink to &quot;シェルのファイル操作&quot;">​</a></h2><p><code>Lertaro.PluginSdk.Shell.FileOperations</code> — Windows シェル自身の <code>IFileOperation</code> への薄いラッパーです。プラグインがファイルを動かしたとき、エクスプローラーと同じ進行状況ダイアログ、同じ「ファイルは既に存在します」の確認、同じ元に戻す項目が出ます。微妙に違う挙動をする <code>System.IO</code> 呼び出しにはなりません。</p><table tabindex="0"><thead><tr><th>ヘルパー</th><th>用途</th></tr></thead><tbody><tr><td><code>ShellPasteHelper</code></td><td><code>PasteAsync(sourcePaths, destinationFolder, move, onCompleted?)</code> — 任意の数のパスを1つのフォルダーへコピー(または移動)します。<strong>1回</strong>のシェル操作にまとめるので、ドライブをまたぐ複数選択でもダイアログは1つだけで、ファイルごとには出ません。投げっぱなしで即座に戻ります:ユーザーが開いたまま放置しうるネイティブダイアログを待ってブロックすれば、呼び出し元が固まるだけだからです。<code>onCompleted</code> は操作が終わった時点で発火します — すべてコピーされたかユーザーが取り消したかを問いません。コピー先を表示しているビューにとって、どちらの答えも「もう一度見に行く」で同じだからです。</td></tr><tr><td><code>ShellDeleteHelper</code></td><td><code>DeleteAsync(paths, permanent)</code> — ごみ箱へ、または完全に削除します。これも1回の操作・1回の確認にまとめられ、同じく投げっぱなしです。</td></tr><tr><td><code>VirtualFileExtractor</code></td><td><code>HasVirtualFiles(dataObject)</code> / <code>Extract(dataObject, targetFolder)</code> — ドラッグが運んでいる、まだディスク上に存在しないファイルを書き出します:ブラウザーからドラッグした画像、メールクライアントからドラッグした添付、zip のプレビューからドラッグしたファイルなど。どれもパスではないので <code>IDataObject.GetData(DataFormats.FileDrop)</code> では何も取れません。実際に届くのは、名前を並べたディスクリプターと、インデックス指定で1つずつ渡されるバイト列で、これはそれを解きほぐします。意図的に種類で絞り込みません:ドラッグ側が渡す気でいるものを拒むには拡張子を信じるかバイトを覗くしかなく、どちらもこのヘルパーの仕事ではないからです。<code>ResolveDestination(folder, name)</code> は「上書きせずに (2) を付ける」という同じ命名規則で、自分でファイルを書き出す呼び出し側のために公開しています。</td></tr></tbody></table><p>非同期の2つは SDK 自身の STA ワーカースレッド(<code>ShellOperationStaWorker</code>、ホストが起動します)で走ります — シェルの COM インターフェイスは STA を要求するので、共有することでプラグインが自前のアパートメントを立てずに済みます。</p>',8)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
